type Ref = { id: string; name: string; status?: string }
export type Item = CatalogueItem & { categoryId?:string|null; status:string; description?:string|null; function?:string|null; link?:string|null; optionSelection?:string|null; remarks?:string|null; catalogueState?:"COMPLETE"|"INCOMPLETE"; balance?: { onHand: string; reserved: string }; free?: number; demand?: string; procurement?: string; deficit?: string; allocationSources?:Array<{demandLineId:string;demandNo:string;destination?:string|null;requester:string;quantity:string}>; procurementOrders?:Array<{quantity:string;order:{id:string;source:string;orderNo:string;status:string;submittedAt?:string|null}}>; purchaseLines?:Array<{quantity:string;purchaseRequest:{id:string;requestNo:string;status:string}}> }
