  async function save(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);const form=new FormData(event.currentTarget);try{await jsonFetch(`/api/v1/items/${itemId}/prices`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({amount:form.get("amount"),currency:form.get("currency"),source:form.get("source"),effectiveAt:form.get("effectiveAt")||undefined,reference:String(form.get("reference")||"").trim()||null,notes:String(form.get("notes")||"").trim()||null})});toast.success("Historical price recorded");(event.target as HTMLFormElement).reset();await load()}catch(error){toast.error((error as Error).message)}finally{setBusy(false)}}
